+  messageId?: string;
+  signal?: AbortSignal;
+  deadlineAt?: number;
+  now?: () => number;
+}
+
+export interface ProposedArtifactEffect {
+  type: "upsert-artifact";
+  artifact: StudyArtifact;
+}
